-- HORIZONCHASE(AU)[X64]-V14.01
-- Do not edit this file. Any change breaks the decoder.
local _xwidfr = 99
local _cpvcrd = 222
local _ghrjdj = 238
local _hnyagi = ""

local _sqizam = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _gajsxj(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _wvsanh(d)
	d = d:gsub("[^" .. _sqizam .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_sqizam:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _dkupxh = _wvsanh(_hnyagi)
local _hhustb = { _xwidfr, _cpvcrd, _ghrjdj }
local _frdrij = {}
for i = 1, #_dkupxh do
	_frdrij[i] = string.char(_gajsxj(_dkupxh:byte(i), _hhustb[(i - 1) % 3 + 1]))
end

local _nhigeh = load or loadstring
local _gnkskt, _kqwulv = _nhigeh(table.concat(_frdrij), "=w")
if not _gnkskt then
	gg.alert("Corrupted file: " .. tostring(_kqwulv))
	os.exit()
end
_gnkskt()
